import {changePages,changeCases} from './market-change-content.mjs';
import {changeView,startChange,resumeChange,setChangePage,chooseTenderRelation,chooseReturn,adjustReturnCoin,exchangeReturnCoins,zeroReturn,addChangeSupport,checkChange,changeCheckMatches,sourceCoinCount,sourceCoinTotal} from './market-change-core.mjs';
import {exchangeResult} from './coin-counter-core.mjs';
import {exchanges} from './coin-counter-content.mjs';
import {practiceCoinArt,practiceCoinPictures,practiceCentDots} from './coin-counter-ui.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(attrs,label,selected=false)=>`<button type="button" class="${selected?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
const quantity=(n,unit)=>`${n} ${unit}${n===1?'':'s'}`;
const relations=[['below','Less than the price'],['exact','Exactly the price'],['above','More than the price'],['unsure','Not sure yet']];
const relationLabel=id=>relations.find(([key])=>key===id)?.[1]||'No comparison chosen';
const returnLabel=id=>id==='amount'?'Use the coin amount':id==='short'?'Payment is short; cannot give change yet':id==='unsure'?'Not sure yet':'No return response yet';
const outcome=value=>value===null?'unobserved':value?'fits':'does not fit';
function textCoins(vector,types){return types.map(c=>`${vector[c.id]??0} ${vector[c.id]===1?c.name.toLowerCase():c.plural}`).map(esc).join('; ');}
function pictures(source,vector,empty='No returned coins'){return source.drawingVersion===1?practiceCoinPictures(vector,source.denominations,empty):`<p class="change-picture-fallback">This saved coin-picture version is unavailable. Exact coin labels remain: ${textCoins(vector,source.denominations)}.</p>`;}
function guideCoin(source,c){return source.drawingVersion===1?practiceCoinArt(c):'<span class="change-no-picture">Coin label</span>';}
function fixedTicket(source,snapshot=null){const coins=snapshot?.coins||source.tender,count=snapshot?snapshot.count:sourceCoinCount(source,coins),value=snapshot?snapshot.value:sourceCoinTotal(source,coins);return `<aside class="change-ticket"><h3>${esc(source.item)}</h3><div class="change-fixed-amounts"><p><strong>Price</strong><span>${quantity(source.price,'cent')}</span></p><p><strong>Handed over</strong><span>${quantity(value,'cent')}</span></p></div>${pictures(source,coins,'No handed-over coins')}<p class="tiny">Handed over: ${quantity(count,'coin')}, ${quantity(value,'cent')}. ${esc(source.unit)} · fictional practice prices.</p></aside>`;}
function read(r){return `<h2 id="change-prompt" tabindex="-1">Does the money handed over cover the price?</h2><p>${esc(r.source.prompt)}</p><div class="change-read-layout">${fixedTicket(r.source)}<section class="change-relation-question"><h3>Compare handed over with price</h3><div class="change-relation-choices" role="group" aria-label="Compare the handed-over value with the price">${relations.map(([id,label])=>button(`data-change-relation="${id}" aria-pressed="${r.relation===id}"`,`${label}${r.relation===id?' · selected':''}`,r.relation===id)).join('')}</div>${button('data-change-relation="clear"','Leave this comparison blank')}${hearButton(r.source.prompt+' Does the money handed over cover the price?','Hear this price and handed-over question')}${button('data-change-page="coins"','Next: choose coins',true)}</section></div><p class="tiny">The price and handed-over coins stay fixed. A return goes back to the customer; it is not a second payment.</p>`;}
function proposalComparison(r){if(r.returnChoice!=='amount')return '';const tender=sourceCoinTotal(r.source,r.source.tender);if(tender<r.source.price)return '<p class="change-proposal-equation">The handed-over amount is below the price. Giving money back cannot make this payment cover it; this is not zero change.</p>';const returned=sourceCoinTotal(r.source,r.coins),sum=r.source.price+returned;return `<p class="change-proposal-equation"><strong>Compare our proposed split:</strong><br>${r.source.price}¢ price + ${returned}¢ return ${sum===tender?'=':sum<tender?'&lt;':'&gt;'} ${tender}¢ handed over</p>`;}
function coinControls(r){return `<div class="change-coin-controls" role="group" aria-label="Change the returned coin idea">${r.source.denominations.map(c=>`<div class="change-coin-editor">${guideCoin(r.source,c)}<span><strong>${esc(c.name)}</strong><small>${quantity(c.value,'cent')} each</small></span>${button(`data-change-coin="${c.id}" data-delta="-1" aria-label="Remove one ${esc(c.name)} from the returned coin idea"${(r.coins[c.id]??0)===0?' disabled':''}`,'−')}<strong>${r.coins[c.id]??0}</strong>${button(`data-change-coin="${c.id}" data-delta="1" aria-label="Add one ${esc(c.name)} to the returned coin idea"`,'＋')}</div>`).join('')}</div>`;}
function exchangeLabel(source,rule){const describe=vector=>Object.entries(vector).map(([id,n])=>{const c=source.denominations.find(c=>c.id===id);return `${n} ${n===1?c.name.toLowerCase():c.plural}`;}).join(' + ');return `${describe(rule.from)} → ${describe(rule.to)}`;}
function supports(r){return `<details id="change-guide" data-round="${r.id}"><summary>Coin names and values</summary><div class="change-coin-guide">${r.source.denominations.map(c=>`<div>${guideCoin(r.source,c)}<strong>${esc(c.name)}</strong><span>${quantity(c.value,'cent')}</span></div>`).join('')}</div><p>Coin count, physical size and value are different. These practice pictures show names and values. Real coins may have different designs.</p></details><details id="change-dots" data-round="${r.id}"><summary>Show value dots · each dot is one cent</summary><p>Dots show value, not more coins. Price: ${quantity(r.source.price,'cent')}.</p>${practiceCentDots(r.source.price)}<p>Handed over: ${quantity(sourceCoinTotal(r.source,r.source.tender),'cent')}.</p>${practiceCentDots(sourceCoinTotal(r.source,r.source.tender))}<p>${r.returnChoice==='amount'?'Proposed return':'Retained inactive coin idea'}: ${quantity(sourceCoinTotal(r.source,r.coins),'cent')}.</p>${practiceCentDots(sourceCoinTotal(r.source,r.coins))}</details><details id="change-exchanges" data-round="${r.id}"><summary>Exchange coins in the return idea</summary><p>The value stays the same while the number of coins may change. A successful exchange explicitly proposes the new coins as our return.</p><div class="change-exchange-buttons">${exchanges.filter(rule=>Object.keys({...rule.from,...rule.to}).every(id=>r.source.denominations.some(c=>c.id===id))).map(rule=>{const result=exchangeResult(r.coins,rule.id);return button(`data-change-exchange="${rule.id}"${result.ok&&sourceCoinTotal(r.source,result.coins)===sourceCoinTotal(r.source,r.coins)?'':' disabled'}`,exchangeLabel(r.source,rule));}).join('')}</div><p class="tiny">Each exchange needs its input coins and room within 25 coins / 50 cents.</p></details>`;}
function compactTicket(r){const source=r.source,tender=source.denominations.filter(c=>source.tender[c.id]>0).map(c=>`${source.tender[c.id]} ${source.tender[c.id]===1?c.name.toLowerCase():c.plural}`).join(', ');return `<aside class="change-compact-ticket"><p><strong>Price ${source.price}¢</strong> · <strong>Handed over ${sourceCoinTotal(source,source.tender)}¢</strong></p><p>${esc(tender)} · ${quantity(sourceCoinCount(source,source.tender),'coin')}. US cents.</p><p>Our comparison: <strong>${esc(relationLabel(r.relation))}</strong>.</p></aside>`;}
function coinIdea(r){return `<div class="change-return-status"><strong>${r.returnChoice==='amount'?'Proposed return':'Retained coin idea'}</strong><p>${r.returnChoice==='amount'?'These coins are proposed to go back.':r.returnChoice==='short'?'Payment short is selected; these coins are inactive.':r.returnChoice==='unsure'?'Not sure is selected; these coins are inactive.':'No return response yet; this coin idea is inactive.'}</p></div><div class="change-return-totals"><span><strong>${sourceCoinCount(r.source,r.coins)}</strong> ${sourceCoinCount(r.source,r.coins)===1?'coin':'coins'}</span><span><strong>${sourceCoinTotal(r.source,r.coins)}</strong> ${sourceCoinTotal(r.source,r.coins)===1?'cent':'cents'}</span></div><div class="change-return-picture">${pictures(r.source,r.coins)}</div>`;}
function coinsPage(r){return `<h2 id="change-prompt" tabindex="-1">Which coins might go back?</h2>${compactTicket(r)}<div class="change-coins-layout"><section class="change-coin-controls-side">${coinControls(r)}</section><section class="change-current-idea">${coinIdea(r)}</section></div>${button('data-change-page="return"','Next: decide the return',true)}<p class="tiny">Next only opens the return decision. Mat limit: 25 coins and 50 cents. A successful edit proposes these coins as our return.</p>${supports(r)}`;}
function returnPage(r){return `<h2 id="change-prompt" tabindex="-1">What should go back to the customer?</h2>${compactTicket(r)}<div class="change-decision-layout"><section class="change-current-idea">${coinIdea(r)}${button('data-change-page="coins"','Edit coins')}</section><section class="change-return-work"><div class="change-return-responses" role="group" aria-label="Choose a returned response">${button(`data-change-return="amount" aria-pressed="${r.returnChoice==='amount'}"`,'Use these coins as our return',r.returnChoice==='amount')}${button('data-change-zero','Return no coins (0¢) · clear this mat')}${button(`data-change-return="short" aria-pressed="${r.returnChoice==='short'}"`,'The payment is short; we cannot give change yet',r.returnChoice==='short')}${button(`data-change-return="unsure" aria-pressed="${r.returnChoice==='unsure'}"`,'Not sure yet',r.returnChoice==='unsure')}</div>${proposalComparison(r)}${button('data-change-check','Check / keep this trail',true)}<p class="tiny">Checking is open with blank choices. Latest 8 checks stay here; a ninth removes the oldest.</p></section></div>`;}
function sourceDetails(source){return `<details class="change-frozen-source"><summary>Original price, handed-over coins and labels kept with this check</summary><p>${esc(source.prompt)}</p>${fixedTicket(source)}<p>${esc(source.help)}</p><ul>${source.denominations.map(c=>`<li>${esc(c.name)} / ${esc(c.plural)}: ${quantity(c.value,'cent')}.</li>`).join('')}</ul></details>`;}
function record(r,c,index){return `<section class="change-record" tabindex="-1"><h3>${index===r.checks.length-1&&changeCheckMatches(r,c)?'Latest check of these choices':'Earlier recorded check'}</h3><p class="change-feedback">${esc(c.feedback)}</p><p><strong>Chosen comparison:</strong> ${esc(relationLabel(c.input.relation))}.<br><strong>Chosen returned response:</strong> ${esc(returnLabel(c.input.returnChoice))}.</p><p><strong>Recorded comparison outcome:</strong> ${outcome(c.relationMatch)}.<br><strong>Recorded return outcome:</strong> ${outcome(c.changeMatch)}.<br><strong>Recorded both responses fit:</strong> ${c.fulfilled?'yes':'no'}.</p><p><strong>Recorded actual handed-over relation:</strong> ${esc(relationLabel(c.actualRelation))}.${c.shortage===null?'':` Recorded shortage: ${quantity(c.shortage,'cent')}.`}</p><details><summary>Coin inputs and recorded counts / values</summary><p>Retained input coins: ${textCoins(c.input.coins,c.source.denominations)}.</p><p>${c.input.returnChoice==='amount'?'These were explicitly proposed as money going back.':'These coins were retained but were not an active return amount.'}</p><p><strong>Recorded handed-over snapshot:</strong> ${quantity(c.tender.count,'coin')}, ${quantity(c.tender.value,'cent')}.</p>${pictures(c.source,c.tender.coins,'No recorded handed-over coins')}<p><strong>Recorded returned-coin snapshot:</strong> ${quantity(c.returned.count,'coin')}, ${quantity(c.returned.value,'cent')}.</p>${pictures(c.source,c.returned.coins,'No recorded return coins')}<p class="tiny">These are stored snapshots, not new calculations. Support: ${esc(c.input.support.join(', ')||'none recorded')}.</p></details>${sourceDetails(c.source)}</section>`;}
function kept(r){return `<h2 id="change-prompt" tabindex="-1">Our kept change trail</h2>${r.checks.length?record(r,r.checks.at(-1),r.checks.length-1):'<p>No trail is kept yet. Both responses and the coin idea remain available.</p>'}${button('data-change-page="return"','Change our return idea',true)} ${button('data-change-page="read"','Read the fixed price and tender')}${r.checks.length>1?`<details><summary>Earlier kept checks (${r.checks.length-1})</summary>${r.checks.slice(0,-1).map((c,i)=>record(r,c,i)).join('')}</details>`:''}`;}
function catalog(v){const n=Math.max(0,v.rounds.length-11);return `<section class="change-catalog"><h2>Choose a market case</h2><p>All six fixed price-and-tender cases are open. Changing a case starts a separate visit.</p><p class="tiny">Up to 12 readable visits stay here.${n?` Starting now removes the oldest ${n} readable ${n===1?'visit':'visits'}.`:' Earlier visits remain within that limit.'}</p><form id="change-start-form"><label for="change-case">Price and handed-over case</label><select id="change-case" name="case">${changeCases.map(s=>`<option value="${s.id}"${v.current?.source.id===s.id?' selected':''}>${esc(s.title)}</option>`).join('')}</select><button type="submit" class="secondary">Start this case</button></form></section>`;}
function history(v){return `${v.rounds.length?`<details><summary>Our change visits (${v.rounds.length})</summary>${[...v.rounds].reverse().map(r=>`<p>${button(`data-change-resume="${r.id}"`,`Visit ${r.id}: ${r.source.title}`)}</p>`).join('')}</details>`:''}${v.earlier.length?`<details><summary>Earlier unreadable work (${v.earlier.length})</summary><p>The original work stays unchanged.</p><pre>${esc(JSON.stringify(v.earlier,null,2))}</pre></details>`:''}`;}
export function marketChangePage(state){const v=changeView(state),r=v.current,heading=`<header class="page-heading"><a class="back" href="#workshop"><span aria-hidden="true">←</span> Workshop</a> <a class="back" href="#workshop/coins">Coin Counter payments</a><h1>Market Change</h1><p>Help the pretend stallkeeper decide what goes back to the customer.</p></header>`;if(v.status==='unavailable')return `<div class="change-page">${heading}<section class="change-sheet"><h2>Earlier work is safe</h2><p>This saved change work uses a format we cannot continue here. It remains unchanged; the Workshop and Coin Counter remain open.</p><details><summary>See saved work</summary><pre>${esc(JSON.stringify(state.marketChange,null,2))}</pre></details></section></div>`;return `<div class="change-page">${heading}<section class="change-sheet">${r?`<nav class="change-tabs" aria-label="Market Change pages">${changePages.map(p=>button(`data-change-page="${p}" aria-current="${v.page===p?'page':'false'}"`,({read:'Read',coins:'Coins',return:'Return',kept:'Kept trail'})[p],v.page===p)).join('')}</nav><p class="change-case-title"><strong>${esc(r.source.title)}</strong>${r.familiar?' · Familiar case':''}</p>`:''}<p id="change-status" class="change-status" role="status" tabindex="-1"></p>${r?v.page==='coins'?coinsPage(r):v.page==='return'?returnPage(r):v.page==='kept'?kept(r):read(r):`<h2 id="change-prompt" tabindex="-1">Read a price and the money handed over</h2><p>US-cent practice props. Price, handed over and returned are different quantities. Café meals and supplies stay separate.</p>${catalog(v)}`}${r?`<details id="change-help" data-round="${r.id}"><summary>Help us think about money going back</summary><p>${esc(r.source.help)}</p>${hearButton(r.source.help,'Hear this change explanation')}${button('data-change-together',r.support.includes('together')?'Thinking together recorded':'We thought together')}</details><details><summary>Choose another market case</summary>${catalog(v)}</details>`:''}</section>${history(v)}</div>`;}
export function marketChangeNotes(state){const v=changeView(state);if(v.status==='missing')return '';if(v.status==='unavailable')return `<details class="panel"><summary>Market Change · earlier format</summary><pre>${esc(JSON.stringify(state.marketChange,null,2))}</pre></details>`;return `<details class="panel change-page"><summary>Market Change (${v.rounds.length} visits)</summary><p>Labeled US-cent change practice with supplied values, not physical cash handling, independent arithmetic fluency or real prices. Live totals/comparisons and previous checked feedback provide teaching: a fitting response does not establish unassisted calculation. Only explicit support requests are recorded as support codes. Tender comparison and return outcomes stay separate; an inactive coin vector is not an amount response. Generic notes downloads retain all frozen sources and recorded snapshots.</p>${v.rounds.map(r=>`<section><h3>Visit ${r.id}: ${esc(r.source.title)}</h3><p>Familiar case as recorded: ${r.familiar?'yes':'no'}. Current comparison: ${esc(relationLabel(r.relation))}. Current return response: ${esc(returnLabel(r.returnChoice))}. Current retained coins: ${textCoins(r.coins,r.source.denominations)}. Support: ${esc(r.support.join(', ')||'none recorded')}.</p>${sourceDetails(r.source)}${r.checks.map((c,i)=>record(r,c,i)).join('')}</section>`).join('')}${v.earlier.length?`<pre>${esc(JSON.stringify(v.earlier,null,2))}</pre>`:''}</details>`;}
export function bindMarketChange(state,{save,render,focus}){
 const boundId=changeView(state).current?.id,sameVisit=el=>el.isConnected&&boundId!==undefined&&changeView(state).current?.id===boundId;
 const show=(message='',target='#change-prompt')=>{const id=changeView(state).current?.id,open=[...document.querySelectorAll('.change-sheet details[id][data-round][open]')].filter(d=>Number(d.dataset.round)===id).map(d=>d.id);save();render();if(changeView(state).current?.id===id)for(const key of open){const d=document.getElementById(key);if(d)d.open=true;}const status=document.querySelector('#change-status');if(status)status.textContent=message;focus?.(target);};
 const bind=(selector,fn)=>document.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>{if(sameVisit(b))fn(b);}));
 document.querySelector('#change-start-form')?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.isConnected||changeView(state).current?.id!==boundId)return;const r=startChange(state,new FormData(form).get('case'));show(r?'A new fixed price-and-tender visit is ready. Earlier checks stay in their visits.':'A new visit cannot be created because its saved visit numbers have reached the supported limit. Earlier visits remain available.',r?'#change-prompt':'#change-status');});
 document.querySelectorAll('[data-change-resume]').forEach(b=>b.addEventListener('click',()=>{if(!b.isConnected||changeView(state).current?.id!==boundId)return;const ok=resumeChange(state,Number(b.dataset.changeResume));show(ok?'Earlier visit opened with its own source and outcomes.':'That visit could not be opened.');}));
 bind('[data-change-page]',b=>{setChangePage(state,b.dataset.changePage);show();});
 bind('[data-change-relation]',b=>{chooseTenderRelation(state,b.dataset.changeRelation==='clear'?null:b.dataset.changeRelation);show('Comparison choice changed. The returned response is unchanged.',`[data-change-relation="${b.dataset.changeRelation}"]`);});
 bind('[data-change-return]',b=>{chooseReturn(state,b.dataset.changeReturn);show(b.dataset.changeReturn==='amount'?'These coins, including an empty mat, are now our explicit return idea.':'Response changed. The coin idea is retained but is not being proposed as a return.',`[data-change-return="${b.dataset.changeReturn}"]`);});
 bind('[data-change-zero]',()=>{zeroReturn(state);show('The returned mat was cleared and zero cents was explicitly proposed.','[data-change-zero]');});
 bind('[data-change-coin]',b=>{const id=b.dataset.changeCoin,delta=Number(b.dataset.delta),result=adjustReturnCoin(state,id,delta),r=changeView(state).current,targetDelta=delta===-1&&(r.coins[id]??0)===0?1:delta;show(result==='changed'?'Coin idea changed and is now our proposed return.':result==='limit'?'The return mat holds at most 25 coins and 50 cents. The coin idea and response did not change.':'No coin changed; an unavailable removal does not create a response.',`[data-change-coin="${id}"][data-delta="${targetDelta}"]`);});
 bind('[data-change-exchange]',b=>{const result=exchangeReturnCoins(state,b.dataset.changeExchange);show(result?.ok?`This mat had ${quantity(result.beforeCount,'coin')} and now has ${quantity(result.afterCount,'coin')}. The value stays ${quantity(result.value,'cent')}; this is now our proposed return.`:'This exchange needs all input coins and room within 25 coins and 50 cents. The response and coins did not change.','#change-exchanges > summary');});
 bind('[data-change-check]',()=>{const c=checkChange(state);if(c)setChangePage(state,'kept');show(c?'Both actual responses and the retained coin idea are kept with separate outcomes.':'This trail could not be kept.',c?'.change-record':'#change-status');});
 bind('[data-change-together]',()=>{addChangeSupport(state,'together');show('Thinking together recorded as support.','[data-change-together]');});
 for(const [id,code]of [['change-help','help'],['change-dots','dots']]){const fold=document.getElementById(id);fold?.addEventListener('toggle',()=>{if(fold.open&&sameVisit(fold)&&Number(fold.dataset.round)===boundId){addChangeSupport(state,code);save();}});}
 document.querySelectorAll('.change-sheet [data-speak]').forEach(b=>b.addEventListener('click',()=>{if(sameVisit(b)){addChangeSupport(state,'audio');save();}}));
}
